"""W3 E1-E5. Predeclared: all 32 section5 cells; strengths 0,.1,.25,.5,1.
E2 pool variants cosine/type/signal; E3 ridge20/100; E4 ridge20/100 and train null screen;
E5 latent rank1/2/4 ridge20. Feature group ablations at best config, train-only fit.
Read shared feature/dense cache; never tune on audit. All source lives in JSON by user request.
"""
import json,time,sys,hashlib
from pathlib import Path
import numpy as np
sys.path.insert(0,str(Path("docs/sai").resolve()))
from harness import evaluate,diff_ci,blend_gain,check_determinism,to_csv,read_pred_csv,write_result,smoke_split
from harness.scoring import audit_episodes
C={}
exec(json.loads(Path('docs/sai/results/W3W4_COMMON.json').read_text())['source'],C)
D=C['load_features']()
V=C['load_validation']()
CONFIGS=D.get('configs',C.get('configs'))
if CONFIGS is None: CONFIGS=C['CONFIGS']
STRENGTHS=[0,.1,.25,.5,1.]
DESCS={'E1':'recent residual pooling across peer machines','E2':'cosine, type and signal peer residual pooling','E3':'train-history episode drift feature correction','E4':'train-screened exact peer lag associations against null controls','E5':'latent episode state factor residual model'}
def norm(p):
    p=np.maximum(np.asarray(p,float),1e-10)
    return p/p.sum(1,keepdims=True)
def freq(b,c):
    return b['freq'][:,int(c['prior'] in [1,'type_signal','type-signal','A2']),int(c['density']),:,:]
def groups(b):
    g={}
    for i,(e,t) in enumerate(zip(b['episode'],b['cutoff'])):g.setdefault((str(e),int(t)),[]).append(i)
    return [np.asarray(v,int) for v in g.values()]
def pool(b,x,mode='all',ref=None):
    out=np.zeros_like(x,dtype=float)
    for ids in groups(b):
        if len(ids)<2:continue
        w=np.ones((len(ids),len(ids)))
        if mode=='cosine':
            r=ref[ids]; r=r/np.maximum(np.linalg.norm(r,axis=1,keepdims=True),1e-12)
            w=np.maximum(r@r.T,0)**4
        elif mode in ['type','signal']:
            z=b['mtype' if mode=='type' else 'signal'][ids]
            w=(z[:,None]==z[None,:]).astype(float)
        np.fill_diagonal(w,0)
        out[ids]=(w@x[ids])/np.maximum(w.sum(1,keepdims=True),1)
    return out
def cellx(b,c):return np.nan_to_num(C['cell_X'](b,c),nan=0,posinf=0,neginf=0)
def groupname(n):
    n=n.lower()
    if 'lag' in n:return 'exact_tick_lags'
    if 'pair' in n:return 'pair_products'
    if any(w in n for w in ['freq','half','hl','ewm']):return 'multi_half_life'
    if any(w in n for w in ['ess','density','observ','fraction']):return 'ess_density'
    if any(w in n for w in ['moment','mean','var','log_mean']):return 'window_moments'
    if any(w in n for w in ['since','last']):return 'time_since_events'
    if any(w in n for w in ['jsd','tv','l2','cusum','drift']):return 'drift_statistics'
    if any(w in n for w in ['peer','episode','loo']):return 'episode_information'
    if any(w in n for w in ['type','signal','interaction']):return 'metadata_interactions'
    if any(w in n for w in ['base','b3','chosen']):return 'baseline_inputs'
    return 'other_catalog_features'
def namedx(b,c,omit=None):
    x=cellx(b,c)
    names=list(b['names'])+[f'b3_probability_{k}' for k in range(5)]+['b3_chosen_hl']
    if len(names)!=x.shape[1]:
        names=[f'feature_{j}' for j in range(x.shape[1])]
    if omit:
        x=x.copy();x[:,[j for j,n in enumerate(names) if groupname(n)==omit]]=0
    return x,names
def state(b,c,omit=None):
    f=freq(b,c); delta=f[:,0]-f[:,1]
    long=f[:,1]
    ep=pool(b,delta)
    tv=.5*np.abs(delta).sum(1,keepdims=True)
    z=np.column_stack([delta,ep,pool(b,tv),pool(b,np.abs(delta)),long])
    if omit=='multi_half_life':z[:,:]=0
    if omit=='episode_information':z[:,5:16]=0
    if omit=='drift_statistics':z[:,:16]=0
    return z
def fitridge(x,y,xx,lam):
    mu=x.mean(0);sd=x.std(0);sd=np.maximum(sd,.01)
    a=(x-mu)/sd;b=(xx-mu)/sd
    a=np.column_stack([np.ones(len(a)),a]);b=np.column_stack([np.ones(len(b)),b])
    penalty=np.eye(a.shape[1])*lam;penalty[0,0]=1e-6
    coef=np.linalg.solve(a.T@a+penalty,a.T@y)
    return b@coef
SELECT_LOG={}
def correction(mid,b,c,j,variant,omit=None):
    f=freq(b,c);delta=f[:,0]-f[:,1]
    if mid=='E1':
        if omit in ['multi_half_life','drift_statistics','episode_information']:return np.zeros_like(delta)
        return pool(b,delta)
    if mid=='E2':
        if omit in ['multi_half_life','drift_statistics','episode_information']:return np.zeros_like(delta)
        mode=variant
        if mode=='signal' and not c['signal']:mode='all'
        if omit=='metadata_interactions' and mode in ['type','signal']:mode='all'
        return pool(b,delta,mode,ref=f[:,1])
    tr=D['roll']; target=np.asarray(tr['future'])-tr['base'][j]
    good=np.isfinite(target).all(1)&(np.asarray(tr['future_n'])>=4)
    tx,tn=namedx(tr,c,omit);vx,vn=namedx(b,c,omit)
    ts,vs=state(tr,c,omit),state(b,c,omit)
    if mid=='E3':
        # episode LOO average of catalogue features, plus explicit synchronized drift statistics.
        tx=np.column_stack([ts,pool(tr,tx)]);vx=np.column_stack([vs,pool(b,vx)])
        return fitridge(tx[good],target[good],vx,float(variant))
    if mid=='E4':
        # Exact-tick lag columns (including explicit missing flags) are supplied by shared cache.
        eligible=[k for k,n in enumerate(tn) if 'lag' in n.lower() and 'pair' not in n.lower()]
        if not eligible:raise ValueError('E4 requires named exact-tick lag and null-control columns')
        tx=pool(tr,tx[:,eligible]);vx=pool(b,vx[:,eligible])
        names=[tn[k] for k in eligible]
        # Null screening uses train-history labels only, never validation q or labels.
        y=np.asarray(tr['outcome'])>0
        xc=tx-tx.mean(0);yc=y-y.mean()
        assoc=np.abs(xc.T@yc)/np.maximum(np.sqrt((xc*xc).sum(0)*(yc*yc).sum()),1e-9)
        import re
        lags=[int(re.search(r'lag[^0-9]*(\d+)',n.lower()).group(1)) if re.search(r'lag[^0-9]*(\d+)',n.lower()) else 0 for n in names]
        null=[k for k,l in enumerate(lags) if 9<=l<=16]
        if not null:raise ValueError('E4 missing train-history null controls lag9–16')
        threshold=float(np.percentile(assoc[null],95))
        keep=[k for k,l in enumerate(lags) if 1<=l<=8 and assoc[k]>threshold]
        SELECT_LOG[str(j)]={'null95':threshold,'selected':[names[k] for k in keep],'associations':{n:float(a) for n,a in zip(names,assoc)}}
        if not keep:return np.zeros((len(vx),5))
        return fitridge(tx[good][:,keep],target[good],vx[:,keep],float(variant))
    # SVD on train-history peer state. Query features projected through the frozen train basis.
    tx=np.column_stack([ts,pool(tr,tx)]);vx=np.column_stack([vs,pool(b,vx)])
    mu=tx[good].mean(0);sd=np.maximum(tx[good].std(0),.01)
    a=(tx[good]-mu)/sd;bb=(vx-mu)/sd
    _,_,vh=np.linalg.svd(a,full_matrices=False)
    rank=min(int(variant),vh.shape[0]);axes=vh[:rank].T
    return fitridge(a@axes,target[good],bb@axes,20.)
def variants(mid):return {'E1':['all'],'E2':['cosine','type','signal'],'E3':[20,100],'E4':[20,100],'E5':[1,2,4]}[mid]
def run(mid,smoke=False):
    start=time.perf_counter(); grid=[];best=None
    keep=np.arange(V.n)
    scope='dev';sv=V
    if smoke:
        sv=smoke_split(V);pos={q:i for i,q in enumerate(V.qid)};keep=np.asarray([pos[q] for q in sv.qid]);scope='smoke'
    for j,c in enumerate(CONFIGS[:1] if smoke else CONFIGS):
        b=D['va'];base=b['base'][j]
        for variant in variants(mid):
            corr=correction(mid,b,c,j,variant)
            for strength in STRENGTHS:
                p=norm(base+strength*corr);ev=evaluate(p[keep],sv,scope,bootstrap=0)
                row={'config_index':j,'params':dict(c,method_variant=variant,strength=strength),**ev}
                grid.append(row)
                if best is None or ev['points']>best[0]:best=(ev['points'],j,variant,strength,p)
    if smoke:
        sm={'id':mid,'smoke':True,'cells':len(grid),'points':best[0],'seconds':time.perf_counter()-start,'n_episodes':len(sv.episodes),'scope':'24 dev episodes; no audit'}
        Path('docs/sai/results/'+mid+'_SMOKE.json').write_text(json.dumps(sm,indent=1)+'\n')
        print(json.dumps(sm),flush=True);return
    _,j,variant,strength,p=best;c=CONFIGS[j]
    ablations=[]
    catalog=['exact_tick_lags','pair_products','multi_half_life','ess_density','window_moments','time_since_events','drift_statistics','episode_information','metadata_interactions','baseline_inputs','other_catalog_features']
    for g in catalog:
        ap=norm(D['va']['base'][j]+strength*correction(mid,D['va'],c,j,variant,g))
        ablations.append({'omitted_feature_group':g,**evaluate(ap,V,'dev',bootstrap=0),'applies_to':'method correction; base frozen at selected section5 cell'})
    fn=lambda unused:norm(D['va']['base'][j]+strength*correction(mid,D['va'],c,j,variant))
    det,p=check_determinism(fn,V)
    if det>=1e-8:raise RuntimeError('determinism failed')
    base=read_pred_csv('docs/sai/preds/B3_validation.csv',V)
    standalone=diff_ci(p,base,V,'dev');stack=blend_gain(p,base,V);stack.pop('oof')
    condition_ci={}
    audit=audit_episodes(V)
    for condition in sorted(set(V.condition)):
        rows=np.array([i for i in range(V.n) if V.episode[i] not in audit and V.condition[i]==condition])
        hybrid=base.copy();hybrid[rows]=p[rows]
        condition_ci[str(condition)]={'effect':'overall points replacing B3 only in named condition',**diff_ci(hybrid,base,V,'dev')}
    elapsed=time.perf_counter()-start
    doc=write_result(mid,'codex',DESCS[mid],dict(c,method_variant=variant,strength=strength),V,p,elapsed,seed=0,stdlib_only=False,determinism=det,extra={'section5_grid':grid,'grid_cell_count':len(grid),'section5_configs_completed':len(CONFIGS),'feature_ablations':ablations,'standalone_vs_B3':standalone,'stack_member':stack,'train_screen':SELECT_LOG if mid=='E4' else None,'condition_paired_ci_vs_B3':condition_ci,'smoke':json.loads(Path('docs/sai/results/'+mid+'_SMOKE.json').read_text()),'selection_caveat':'Method/config selected using all dev episodes; OOF blend weights exclude each fold but member hyperparameters are not nested. Stack CI is conditional on dev selection.','audit_touched':False,'source':'results/W3_IMPLEMENTATION.json','selection_scope':'dev; structural fitting on train-history rolling pseudo-cutoffs','predeclared_strength_grid':STRENGTHS,'roll_target':'future window32; strictly train histories','method_runtime_includes_grid':True})
    to_csv('docs/sai/results/preds/'+mid+'_validation.csv',V,p)
    report=[mid+': '+DESCS[mid],f"Completed 32 section5 configs x {len(variants(mid))} variants x 5 strengths = {len(grid)} cells.",f"Best params: {json.dumps(doc['params'],sort_keys=True)}",f"Dev points {doc['points']:.6f}; CI95 {doc['ci95']}",f"Condition ratios {json.dumps(doc['condition_ratios'],sort_keys=True)}",f"Class error shares {json.dumps(doc['class_error_shares'],sort_keys=True)}",f"Paired standalone vs B3 {json.dumps(standalone)}",f"Episode-OOF stack member {json.dumps(stack)}",f"Runtime {elapsed:.3f}s; determinism max difference {det}; seed0; stdlib-only no.",f"Feature ablations: {len(ablations)}, correction features only; fixed selected base.",'Audit episodes excluded from all scoring and selection; full validation predictions saved.','Source retained in results/W3_IMPLEMENTATION.json; shared cache read without rebuilding.']
    Path('docs/sai/reports/'+mid+'.md').write_text('\n'.join(report)+'\n')
    print(json.dumps({'id':mid,'points':doc['points'],'runtime':elapsed,'cells':len(grid),'stack_gain':stack['vs_base']}),flush=True)
if __name__=='__main__':
    run(sys.argv[1],len(sys.argv)>2 and sys.argv[2]=='smoke')
